@Composable
fun ConnectivityObserver(manager: ConnectivityManager) {
    val callback = remember { NetworkCallback() }
    DisposableEffect(manager, callback) {
        manager.registerDefaultNetworkCallback(callback)
        onDispose { manager.unregisterNetworkCallback(callback) }
    }
}

