@Composable
fun SensorEffect(onValue: (Float) -> Unit) {
    val latest by rememberUpdatedState(onValue)
    DisposableEffect(Unit) {
        val listener = SensorListener { latest(it) }
        register(listener)
        onDispose { unregister(listener) }
    }
}

